38:         else {
39:             return (self.bounds.contains(point) ? self : nil)
40:         }
41:     }
42:     
43:     func handleControl(_ view: UIView?, controlEvent: UIControlEvents) {
44:         if let control = view as? UIControl {
45:             let targets = control.allTargets
46:             for target in targets {
47:                 if let actions = control.actions(forTarget: target, forControlEvent: controlEvent) {
48:                     for action in actions {
49:                         let selectorString = action
50:                         let selector = Selector(selectorString)
51:                         control.sendAction(selector, to: target, for: nil)
52:                     }
53:                     
54:                 }
55:             }
56:         }
57:     }
58:     
59:     // TODO: there's a bit of "stickiness" to Apple's implementation
60:     func findNearestView(_ position: CGPoint) -> UIView? {
61:         if !self.bounds.contains(position) {
62:             return nil
63:         }
64:         
65:         var closest: (UIView, CGFloat)? = nil
66:         
67:         for anyView in self.subviews {
68:             let view = anyView
69:             if view.isHidden {
70:                 continue
71:             }
72:             
73:             view.alpha = 1
74:             
75:             let distance = distanceBetween(view.frame, point: position)
76:             
77:             if closest != nil {
78:                 if distance < closest!.1 {
79:                     closest = (view, distance)
80:                 }
81:             }
82:             else {
83:                 closest = (view, distance)
84:             }
85:         }
86:         
87:         if closest != nil {
88:             return closest!.0
89:         }
90:         else {
91:             return nil
92:         }
93:     }
94:     
95:     // http://stackoverflow.com/questions/3552108/finding-closest-object-to-cgpoint b/c I'm lazy
96:     func distanceBetween(_ rect: CGRect, point: CGPoint) -> CGFloat {
97:         if rect.contains(point) {
98:             return 0
99:         }
100: 
101:         var closest = rect.origin
102:         
103:         if (rect.origin.x + rect.size.width < point.x) {
104:             closest.x += rect.size.width
105:         }
106:         else if (point.x > rect.origin.x) {
107:             closest.x = point.x
108:         }
109:         if (rect.origin.y + rect.size.height < point.y) {
110:             closest.y += rect.size.height
111:         }
112:         else if (point.y > rect.origin.y) {
113:             closest.y = point.y
114:         }
115:         
116:         let a = pow(Double(closest.y - point.y), 2)
117:         let b = pow(Double(closest.x - point.x), 2)
118:         return CGFloat(sqrt(a + b));
119:     }
120:     
121:     // reset tracked views without cancelling current touch
122:     func resetTrackedViews() {
123:         for view in self.touchToView.values {
124:             self.handleControl(view, controlEvent: .touchCancel)
125:         }
126:         self.touchToView.removeAll(keepingCapacity: true)
127:     }
128:     
129:     func ownView(_ newTouch: UITouch, viewToOwn: UIView?) -> Bool {
130:         var foundView = false
131:         
132:         if viewToOwn != nil {
133:             for (touch, view) in self.touchToView {
134:                 if viewToOwn == view {
135:                     if touch == newTouch {
136:                         break
137:                     }
138:                     else {
139:                         self.touchToView[touch] = nil
140:                         foundView = true
141:                     }
142:                     break
143:                 }
144:             }
145:         }
146:         
147:         self.touchToView[newTouch] = viewToOwn
148:         return foundView
149:     }
150:     
151:     override func touchesBegan(_ touches: Set<UITouch>, with event: UIEvent?) {
152:         for touch in touches {
153:             let position = touch.location(in: self)
154:             let view = findNearestView(position)
155:             
156:             let viewChangedOwnership = self.ownView(touch, viewToOwn: view)
157:             
158:             if !viewChangedOwnership {
159:                 self.handleControl(view, controlEvent: .touchDown)
160:                 
161:                 if touch.tapCount > 1 {
162:                     // two events, I think this is the correct behavior but I have not tested with an actual UIControl
163:                     self.handleControl(view, controlEvent: .touchDownRepeat)
164:                 }
165:             }
166:         }
167:     }
168:     
169:     override func touchesMoved(_ touches: Set<UITouch>, with event: UIEvent?) {
170:         for touch in touches {
171:             let position = touch.location(in: self)
172:             
173:             let oldView = self.touchToView[touch]
174:             let newView = findNearestView(position)
175:             
176:             if oldView != newView {
177:                 self.handleControl(oldView, controlEvent: .touchDragExit)
178:                 
179:                 let viewChangedOwnership = self.ownView(touch, viewToOwn: newView)
180:                 
181:                 if !viewChangedOwnership {
182:                     self.handleControl(newView, controlEvent: .touchDragEnter)
183:                 }
184:                 else {
185:                     self.handleControl(newView, controlEvent: .touchDragInside)
186:                 }
187:             }
188:             else {
189:                 self.handleControl(oldView, controlEvent: .touchDragInside)
190:             }
191:         }
192:     }
193:     
194:     override func touchesEnded(_ touches: Set<UITouch>, with event: UIEvent?) {
195:         for touch in touches {
196:             let view = self.touchToView[touch]
197:             
198:             let touchPosition = touch.location(in: self)
199:             
200:             if self.bounds.contains(touchPosition) {
201:                 self.handleControl(view, controlEvent: .touchUpInside)
202:             }
203:             else {
204:                 self.handleControl(view, controlEvent: .touchCancel)
205:             }
206:             
207:             self.touchToView[touch] = nil
208:         }
209:     }
210: 
211:     override func touchesCancelled(_ touches: Set<UITouch>, with event: UIEvent?) {
212:         for touch in touches {
213:             let view = self.touchToView[touch]
214:             
215:             self.handleControl(view, controlEvent: .touchCancel)
216:             
217:             self.touchToView[touch] = nil
218:         }
219:     }
220: }
