228:     func refreshShapes() {
229:         // TODO: dunno why this is necessary
230:         self.background.setNeedsLayout()
231:         
232:         self.background.layoutIfNeeded()
233:         self.popup?.layoutIfNeeded()
234:         self.connector?.layoutIfNeeded()
235:         
236:         let testPath = UIBezierPath()
237:         let edgePath = UIBezierPath()
238:         
239:         let unitSquare = CGRect(x: 0, y: 0, width: 1, height: 1)
240:         
241:         // TODO: withUnder
242:         let addCurves = { (fromShape: KeyboardKeyBackground?, toPath: UIBezierPath, toEdgePaths: UIBezierPath) -> Void in
243:             if let shape = fromShape {
244:                 let path = shape.fillPath
245:                 let translatedUnitSquare = self.displayView.convert(unitSquare, from: shape)
246:                 let transformFromShapeToView = CGAffineTransform(translationX: translatedUnitSquare.origin.x, y: translatedUnitSquare.origin.y)
247:                 path?.apply(transformFromShapeToView)
248:                 if path != nil { toPath.append(path!) }
249:                 if let edgePaths = shape.edgePaths {
250:                     for (_, anEdgePath) in edgePaths.enumerated() {
251:                         let editablePath = anEdgePath
252:                         editablePath.apply(transformFromShapeToView)
253:                         toEdgePaths.append(editablePath)
254:                     }
255:                 }
256:             }
257:         }
258:         
259:         addCurves(self.popup, testPath, edgePath)
260:         addCurves(self.connector, testPath, edgePath)
261:         
262:         let shadowPath = UIBezierPath(cgPath: testPath.cgPath)
263:         
264:         addCurves(self.background, testPath, edgePath)
265:         
266:         let underPath = self.background.underPath
267:         let translatedUnitSquare = self.displayView.convert(unitSquare, from: self.background)
268:         let transformFromShapeToView = CGAffineTransform(translationX: translatedUnitSquare.origin.x, y: translatedUnitSquare.origin.y)
269:         underPath?.apply(transformFromShapeToView)
270:         
271:         CATransaction.begin()
272:         CATransaction.setDisableActions(true)
273:         
274:         if let _ = self.popup {
275:             self.shadowLayer.shadowPath = shadowPath.cgPath
276:         }
277:         
278:         self.underView?.curve = underPath
279:         self.displayView.curve = testPath
280:         self.borderView?.curve = edgePath
281:         
282:         if let borderLayer = self.borderView?.layer as? CAShapeLayer {
283:             borderLayer.strokeColor = UIColor.green.cgColor
284:         }
285:         
286:         CATransaction.commit()
287:     }
