332:     func updateColors() {
333:         CATransaction.begin()
334:         CATransaction.setDisableActions(true)
335:         
336:         let switchColors = self.isHighlighted || self.isSelected
337:         
338:         if switchColors {
339:             if let downColor = self.downColor {
340:                 self.displayView.fillColor = downColor
341:             }
342:             else {
343:                 self.displayView.fillColor = self.color
344:             }
345:             
346:             if let downUnderColor = self.downUnderColor {
347:                 self.underView?.fillColor = downUnderColor
348:             }
349:             else {
350:                 self.underView?.fillColor = self.underColor
351:             }
352:             
353:             if let downBorderColor = self.downBorderColor {
354:                 self.borderView?.strokeColor = downBorderColor
355:             }
356:             else {
357:                 self.borderView?.strokeColor = self.borderColor
358:             }
359:             
360:             if let downTextColor = self.downTextColor {
361:                 self.label.textColor = downTextColor
362:                 self.popupLabel?.textColor = downTextColor
363:                 self.shape?.color = downTextColor
364:             }
365:             else {
366:                 self.label.textColor = self.textColor
367:                 self.popupLabel?.textColor = self.textColor
368:                 self.shape?.color = self.textColor
369:             }
370:         }
371:         else {
372:             self.displayView.fillColor = self.color
373:             
374:             self.underView?.fillColor = self.underColor
375:             
376:             self.borderView?.strokeColor = self.borderColor
377:             
378:             self.label.textColor = self.textColor
379:             self.popupLabel?.textColor = self.textColor
380:             self.shape?.color = self.textColor
381:         }
382:         
383:         if self.popup != nil {
384:             self.displayView.fillColor = self.popupColor
385:         }
386:         
387:         CATransaction.commit()
388:     }
