392:         
393:         if let popup = self.popup {
394:             if let delegate = self.delegate {
395:                 let frame = delegate.popupFrame(for: self, direction: dir)
396:                 popup.frame = frame
397:                 popupLabel?.frame = popup.bounds
398:             }
399:             else {
