406:     func configurePopup(_ direction: Direction) {
407:         assert(self.popup != nil, "popup not found")
408:         
409:         self.background.attach(direction)
410:         self.popup!.attach(direction.opposite())
411:         
412:         let kv = self.background
413:         let p = self.popup!
414:         
415:         self.connector?.removeFromSuperview()
416:         self.connector = KeyboardConnector(cornerRadius: 4, underOffset: self.underOffset, start: kv, end: p, startConnectable: kv, endConnectable: p, startDirection: direction, endDirection: direction.opposite())
417:         self.connector!.layer.zPosition = -1
418:         self.addSubview(self.connector!)
419:         
420: //        self.drawBorder = true
421:         
422:         if direction == Direction.up {
423: //            self.popup!.drawUnder = false
424: //            self.connector!.drawUnder = false
425:         }
426:     }
