428:     func showPopup() {
429:         if self.popup == nil {
430:             self.layer.zPosition = 1000
431:             
432:             let popup = KeyboardKeyBackground(cornerRadius: 9.0, underOffset: self.underOffset)
433:             self.popup = popup
434:             self.addSubview(popup)
435:             
436:             let popupLabel = UILabel()
437:             popupLabel.textAlignment = self.label.textAlignment
438:             popupLabel.baselineAdjustment = self.label.baselineAdjustment
439:             popupLabel.font = self.label.font.withSize(22 * 2)
440:             popupLabel.adjustsFontSizeToFitWidth = self.label.adjustsFontSizeToFitWidth
441:             popupLabel.minimumScaleFactor = CGFloat(0.1)
442:             popupLabel.isUserInteractionEnabled = false
443:             popupLabel.numberOfLines = 1
444:             popupLabel.frame = popup.bounds
445:             popupLabel.text = self.label.text
446:             popup.addSubview(popupLabel)
447:             self.popupLabel = popupLabel
448:             
449:             self.label.isHidden = true
450:         }
451:     }
452:     
453:     func hidePopup() {
454:         if self.popup != nil {
455:             self.delegate?.willHidePopup(for: self)
456:             
457:             self.popupLabel?.removeFromSuperview()
458:             self.popupLabel = nil
459:             
460:             self.connector?.removeFromSuperview()
461:             self.connector = nil
462:             
463:             self.popup?.removeFromSuperview()
464:             self.popup = nil
465:             
466:             self.label.isHidden = false
467:             self.background.attach(nil)
468:             
469:             self.layer.zPosition = 0
470:             
471:             self.popupDirection = nil
472:         }
473:     }
