476: /*
477:     PERFORMANCE NOTES
478: 
479:     * CAShapeLayer: convenient and low memory usage, but chunky rotations
480:     * drawRect: fast, but high memory usage (looks like there's a backing store for each of the 3 views)
481:     * if I set CAShapeLayer to shouldRasterize, perf is *almost* the same as drawRect, while mem usage is the same as before
482:     * oddly, 3 CAShapeLayers show the same memory usage as 1 CAShapeLayer — where is the backing store?
483:     * might want to move to drawRect with combined draw calls for performance reasons — not clear yet
484: */
485: 
486: class ShapeView: UIView {
487:     
488:     var shapeLayer: CAShapeLayer?
489: 
490:     override class var layerClass : AnyClass {
491:         return CAShapeLayer.self
492:     }
493:     
494:     var curve: UIBezierPath? {
495:         didSet {
496:             if let layer = self.shapeLayer {
497:                 layer.path = curve?.cgPath
498:             }
499:             else {
500:                 self.setNeedsDisplay()
501:             }
502:         }
503:     }
504:     
505:     var fillColor: UIColor? {
506:         didSet {
507:             if let layer = self.shapeLayer {
508:                 layer.fillColor = fillColor?.cgColor
509:             }
510:             else {
511:                 self.setNeedsDisplay()
512:             }
513:         }
514:     }
515: 
516:     var strokeColor: UIColor? {
517:         didSet {
518:             if let layer = self.shapeLayer {
519:                 layer.strokeColor = strokeColor?.cgColor
520:             }
521:             else {
522:                 self.setNeedsDisplay()
523:             }
524:         }
525:     }
526:     
527:     var lineWidth: CGFloat? {
528:         didSet {
529:             if let layer = self.shapeLayer {
530:                 if let lineWidth = self.lineWidth {
531:                     layer.lineWidth = lineWidth
532:                 }
533:             }
534:             else {
535:                 self.setNeedsDisplay()
536:             }
537:         }
538:     }
539:     
540:     convenience init() {
541:         self.init(frame: CGRect.zero)
542:     }
543:     
544:     override init(frame: CGRect) {
545:         super.init(frame: frame)
546:         
547:         self.shapeLayer = self.layer as? CAShapeLayer
548:         
549:         // optimization: off by default to ensure quick mode transitions; re-enable during rotations
550:         //self.layer.shouldRasterize = true
551:         //self.layer.rasterizationScale = UIScreen.mainScreen().scale
552:     }
553:     
554:     required init?(coder aDecoder: NSCoder) {
555:         fatalError("init(coder:) has not been implemented")
556:     }
557:     
558:     func drawCall(_ rect:CGRect) {
559:         if self.shapeLayer == nil {
560:             if let curve = self.curve {
561:                 if let lineWidth = self.lineWidth {
562:                     curve.lineWidth = lineWidth
563:                 }
564:                 
565:                 if let fillColor = self.fillColor {
566:                     fillColor.setFill()
567:                     curve.fill()
568:                 }
569:                 
570:                 if let strokeColor = self.strokeColor {
571:                     strokeColor.setStroke()
572:                     curve.stroke()
573:                 }
574:             }
575:         }
576:     }
