26:   // MARK: CustomKeyobardShiftState
27:   public enum CustomKeyboardShiftState {
28:     case Once
29:     case Off
30:     case On
31:   }
32: 
33:   // MARK: CustomKeyboardLayoutState
34:   public enum CustomKeyboardLayoutState {
35:     case Letters(shiftState: CustomKeyboardShiftState)
36:     case Numbers
37:     case Symbols
38:   }
39: 
40:   public private(set) var keyboardLayoutState: CustomKeyboardLayoutState = .Letters(shiftState: CustomKeyboardShiftState.Once) {
41:     didSet {
42:       keyboardLayoutStateDidChange(oldState: oldValue, newState: keyboardLayoutState)
43:     }
44:   }
45: 
46:   // MARK: Shift
47:   public var shiftToggleInterval: NSTimeInterval = 0.5
48:   private var shiftToggleTimer: NSTimer?
49: 
50:   // MARK: Backspace
51:   public var backspaceDeleteInterval: NSTimeInterval = 0.1
52:   public var backspaceAutoDeleteModeInterval: NSTimeInterval = 0.5
53:   private var backspaceDeleteTimer: NSTimer?
54:   private var backspaceAutoDeleteModeTimer: NSTimer?
55: 
56:   // MARK: KeyMenu
57:   public var keyMenuLocked: Bool = false
58:   public var keyMenuOpenTimer: NSTimer?
59:   public var keyMenuOpenTimeInterval: NSTimeInterval = 1
60:   public var keyMenuShowingKeyboardButton: KeyboardButton? {
61:     didSet {
62:       oldValue?.showKeyPop(show: false)
63:       oldValue?.showKeyMenu(show: false)
64:       keyMenuShowingKeyboardButton?.showKeyPop(show: false)
65:       keyMenuShowingKeyboardButton?.showKeyMenu(show: true)
66:       dispatch_after(
67:         dispatch_time(DISPATCH_TIME_NOW, Int64(0.1 * Double(NSEC_PER_SEC))),
68:         dispatch_get_main_queue()) { [weak self] in
69:           self?.getCurrentKeyboardLayout().typingEnabled = self!.keyMenuShowingKeyboardButton == nil && self!.keyMenuLocked == false
70:       }
71:     }
72:   }
