74:   // MARK: Init
75:   public init() {
76:     super.init(frame: CGRect.zero)
77:     defaultInit()
78:   }
79: 
80:   public override init(frame: CGRect) {
81:     super.init(frame: frame)
82:     defaultInit()
83:   }
84: 
85:   public required init?(coder aDecoder: NSCoder) {
86:     super.init(coder: aDecoder)
87:     defaultInit()
88:   }
