90:   private func defaultInit() {
91:     keyboardLayout = CustomKeyboardLayout()
92:     keyboardLayoutStateDidChange(oldState: nil, newState: keyboardLayoutState)
93:   }
94: 
95:   // MARK: Layout
96:   public override func layoutSubviews() {
97:     super.layoutSubviews()
98: 
99:     getCurrentKeyboardLayout().frame = CGRect(
100:       x: 0,
101:       y: 0,
102:       width: frame.size.width,
103:       height: frame.size.height)
104:   }
