106:   // MARK: KeyboardLayout
107:   public func getKeyboardLayout(ofState state: CustomKeyboardLayoutState) -> KeyboardLayout {
108:     switch state {
109:     case .Letters(let shiftState):
110:       switch shiftState {
111:       case .Once:
112:         return keyboardLayout.uppercase
113:       case .On:
114:         return keyboardLayout.uppercaseToggled
115:       case .Off:
116:         return keyboardLayout.lowercase
117:       }
118:     case .Numbers:
119:       return keyboardLayout.numbers
120:     case .Symbols:
121:       return keyboardLayout.symbols
122:     }
123:   }
124: 
125:   public func getCurrentKeyboardLayout() -> KeyboardLayout {
126:     return getKeyboardLayout(ofState: keyboardLayoutState)
127:   }
128: 
129:   public func enumerateKeyboardLayouts(enumerate: (KeyboardLayout) -> Void) {
130:     let layouts = [
131:       keyboardLayout.uppercase,
132:       keyboardLayout.uppercaseToggled,
133:       keyboardLayout.lowercase,
134:       keyboardLayout.numbers,
135:       keyboardLayout.symbols,
136:     ]
137: 
138:     for layout in layouts {
139:       enumerate(layout)
140:     }
141:   }
142: 
143:   public func keyboardLayoutStateDidChange(oldState oldState: CustomKeyboardLayoutState?, newState: CustomKeyboardLayoutState) {
144:     // Remove old keyboard layout
145:     if let oldState = oldState {
146:       let oldKeyboardLayout = getKeyboardLayout(ofState: oldState)
147:       oldKeyboardLayout.delegate = nil
148:       oldKeyboardLayout.removeFromSuperview()
149:     }
150: 
151:     // Add new keyboard layout
152:     let newKeyboardLayout = getKeyboardLayout(ofState: newState)
153:     newKeyboardLayout.delegate = self
154:     addSubview(newKeyboardLayout)
155:     setNeedsLayout()
156:   }
157: 
158:   public func reload() {
159:     // Remove current
160:     let currentLayout = getCurrentKeyboardLayout()
161:     currentLayout.delegate = nil
162:     currentLayout.removeFromSuperview()
163:     // Reload layout
164:     keyboardLayout = CustomKeyboardLayout()
165:     keyboardLayoutStateDidChange(oldState: nil, newState: keyboardLayoutState)
166:   }
