168:   // MARK: Capitalize
169:   public func switchToLetters(shiftState shift: CustomKeyboardShiftState) {
170:     keyboardLayoutState = .Letters(shiftState: shift)
171:   }
172: 
173:   public func capitalize() {
174:     switchToLetters(shiftState: .Once)
175:   }
