177:   // MARK: Backspace Auto Delete
178:   private func startBackspaceAutoDeleteModeTimer() {
179:     backspaceAutoDeleteModeTimer = NSTimer.scheduledTimerWithTimeInterval(
180:       backspaceAutoDeleteModeInterval,
181:       target: self,
182:       selector: #selector(CustomKeyboard.startBackspaceAutoDeleteMode),
183:       userInfo: nil,
184:       repeats: false)
185:   }
186: 
187:   private func startBackspaceDeleteTimer() {
188:     backspaceDeleteTimer = NSTimer.scheduledTimerWithTimeInterval(
189:       backspaceDeleteInterval,
190:       target: self,
191:       selector: #selector(CustomKeyboard.autoDelete),
192:       userInfo: nil,
193:       repeats: true)
194:   }
195: 
196:   private func invalidateBackspaceAutoDeleteModeTimer() {
197:     backspaceAutoDeleteModeTimer?.invalidate()
198:     backspaceAutoDeleteModeTimer = nil
199:   }
200: 
201:   private func invalidateBackspaceDeleteTimer() {
202:     backspaceDeleteTimer?.invalidate()
203:     backspaceDeleteTimer = nil
204:   }
205: 
206:   internal func startBackspaceAutoDeleteMode() {
207:     invalidateBackspaceDeleteTimer()
208:     startBackspaceDeleteTimer()
209:   }
210: 
211:   internal func autoDelete() {
212:     delegate?.customKeyboardBackspaceButtonPressed?(self)
213:   }
214: 
215:   // MARK: Shift Toggle
216:   private func startShiftToggleTimer() {
217:     shiftToggleTimer = NSTimer.scheduledTimerWithTimeInterval(
218:       shiftToggleInterval,
219:       target: self,
220:       selector: #selector(CustomKeyboard.invalidateShiftToggleTimer),
221:       userInfo: nil,
222:       repeats: false)
223:   }
224: 
225:   internal func invalidateShiftToggleTimer() {
226:     shiftToggleTimer?.invalidate()
227:     shiftToggleTimer = nil
228:   }
229: 
230:   // MARK: KeyMenu Toggle
231:   private func startKeyMenuOpenTimer(forKeyboardButton keyboardButton: KeyboardButton) {
232:     keyMenuOpenTimer = NSTimer.scheduledTimerWithTimeInterval(
233:       keyMenuOpenTimeInterval,
234:       target: self,
235:       selector: #selector(CustomKeyboard.openKeyMenu(_:)),
236:       userInfo: keyboardButton,
237:       repeats: false)
238:   }
239: 
240:   private func invalidateKeyMenuOpenTimer() {
241:     keyMenuOpenTimer?.invalidate()
242:     keyMenuOpenTimer = nil
243:   }
244: 
245:   public func openKeyMenu(timer: NSTimer) {
246:     if let userInfo = timer.userInfo, keyboardButton = userInfo as? KeyboardButton {
247:       keyMenuShowingKeyboardButton = keyboardButton
248:     }
249:   }
250: 
251:   // MARK: KeyboardLayoutDelegate
252:   public func keyboardLayout(keyboardLayout: KeyboardLayout, didKeyPressStart keyboardButton: KeyboardButton) {
253:     invalidateBackspaceAutoDeleteModeTimer()
254:     invalidateBackspaceDeleteTimer()
255:     invalidateKeyMenuOpenTimer()
256: 
257:     // Backspace
258:     if keyboardButton.identifier == CustomKeyboardIdentifier.Backspace.rawValue {
259:       startBackspaceAutoDeleteModeTimer()
260:     }
261: 
262:     // KeyPop and KeyMenu
263:     if keyboardButton.style.keyPopType != nil {
264:       keyboardButton.showKeyPop(show: true)
265:       if keyboardButton.keyMenu != nil {
266:         startKeyMenuOpenTimer(forKeyboardButton: keyboardButton)
267:       }
268:     } else if keyboardButton.keyMenu != nil {
269:       keyMenuShowingKeyboardButton = keyboardButton
270:       keyMenuLocked = false
271:     }
272:   }
273: 
274:   public func keyboardLayout(keyboardLayout: KeyboardLayout, didKeyPressEnd keyboardButton: KeyboardButton) {
275:     delegate?.customKeyboard?(self, keyboardButtonPressed: keyboardButton)
276: 
277:     // If keyboard key is pressed notify no questions asked
278:     if case KeyboardButtonType.Key(let text) = keyboardButton.type {
279:       delegate?.customKeyboard?(self, keyButtonPressed: text)
280: 
281:       // If shift state was CustomKeyboardShiftState.Once then make keyboard layout lowercase
282:       if case CustomKeyboardLayoutState.Letters(let shiftState) = keyboardLayoutState where shiftState == CustomKeyboardShiftState.Once {
283:         keyboardLayoutState = CustomKeyboardLayoutState.Letters(shiftState: .Off)
284:         return
285:       }
286:     }
287: 
288:     // Chcek special keyboard buttons
289:     if let keyId = keyboardButton.identifier, identifier = CustomKeyboardIdentifier(rawValue: keyId) {
290:       switch identifier {
291: 
292:       // Notify special keys
293:       case .Backspace:
294:         delegate?.customKeyboardBackspaceButtonPressed?(self)
295:       case .Space:
296:         delegate?.customKeyboardSpaceButtonPressed?(self)
297:       case .Globe:
298:         delegate?.customKeyboardGlobeButtonPressed?(self)
299:       case .Return:
300:         delegate?.customKeyboardReturnButtonPressed?(self)
301: 
302:       // Update keyboard layout state
303:       case .Letters:
304:         keyboardLayoutState = .Letters(shiftState: .Off)
305:       case .Numbers:
306:         keyboardLayoutState = .Numbers
307:       case .Symbols:
308:         keyboardLayoutState = .Symbols
309: 
310:       // Update shift state
311:       case .ShiftOff:
312:         if shiftToggleTimer == nil {
313:           keyboardLayoutState = .Letters(shiftState: .Once)
314:           startShiftToggleTimer()
315:         } else {
316:           keyboardLayoutState = .Letters(shiftState: .On)
317:           invalidateShiftToggleTimer()
318:         }
319:       case .ShiftOnce:
320:         if shiftToggleTimer == nil {
321:           keyboardLayoutState = .Letters(shiftState: .Off)
322:           startShiftToggleTimer()
323:         } else {
324:           keyboardLayoutState = .Letters(shiftState: .On)
325:           invalidateShiftToggleTimer()
326:         }
327:       case .ShiftOn:
328:         if shiftToggleTimer == nil {
329:           keyboardLayoutState = .Letters(shiftState: .Off)
330:         }
331:       }
332:     }
333:   }
334: 
335:   public func keyboardLayout(keyboardLayout: KeyboardLayout, didTouchesBegin touches: Set<UITouch>) {
336:     // KeyMenu
337:     if let menu = keyMenuShowingKeyboardButton?.keyMenu, touch = touches.first {
338:       menu.updateSelection(touchLocation: touch.locationInView(self), inView: self)
339:     }
340:   }
341: 
342:   public func keyboardLayout(keyboardLayout: KeyboardLayout, didTouchesMove touches: Set<UITouch>) {
343:     // KeyMenu
344:     if let menu = keyMenuShowingKeyboardButton?.keyMenu, touch = touches.first {
345:       menu.updateSelection(touchLocation: touch.locationInView(self), inView: self)
346:     }
347:   }
348: 
349:   public func keyboardLayout(keyboardLayout: KeyboardLayout, didTouchesEnd touches: Set<UITouch>?)  {
350:     invalidateBackspaceAutoDeleteModeTimer()
351:     invalidateBackspaceDeleteTimer()
352:     invalidateKeyMenuOpenTimer()
353: 
354:     // KeyMenu
355:     if let menu = keyMenuShowingKeyboardButton?.keyMenu, touch = touches?.first {
356:       menu.updateSelection(touchLocation: touch.locationInView(self), inView: self)
357:       // select item
358:       if menu.selectedIndex >= 0 {
359:         if let item = menu.items[safe: menu.selectedIndex] {
360:           item.action?(keyMenuItem: item)
361:         }
362:         keyMenuShowingKeyboardButton = nil
363:         keyMenuLocked = false
364:       } else {
365:         if keyMenuLocked {
366:           keyMenuShowingKeyboardButton = nil
367:           keyMenuLocked = false
368:           return
369:         }
370:         keyMenuLocked = true
371:       }
372:     }
373:   }
374: 
375:   public func keyboardLayout(keyboardLayout: KeyboardLayout, didTouchesCancel touches: Set<UITouch>?) {
376:     invalidateBackspaceAutoDeleteModeTimer()
377:     invalidateBackspaceDeleteTimer()
378:     invalidateKeyMenuOpenTimer()
379: 
380:     // KeyMenu
381:     if let menu = keyMenuShowingKeyboardButton?.keyMenu, touch = touches?.first {
382:       menu.updateSelection(touchLocation: touch.locationInView(self), inView: self)
383:       // select item
384:       if menu.selectedIndex >= 0 {
385:         if let item = menu.items[safe: menu.selectedIndex] {
386:           item.action?(keyMenuItem: item)
387:         }
388:         keyMenuShowingKeyboardButton = nil
389:         keyMenuLocked = false
390:       } else {
391:         if keyMenuLocked {
392:           keyMenuShowingKeyboardButton = nil
393:           keyMenuLocked = false
394:           getCurrentKeyboardLayout().typingEnabled = true
395:           return
396:         }
397:         keyMenuLocked = true
398:       }
399:     }
400:   }
401: }
