59: // MARK: - KeyboardLayout
60: public class KeyboardLayout: UIView {
61:   public var style: KeyboardLayoutStyle!
62:   public var rows: [KeyboardRow]!
63: 
64:   public weak var delegate: KeyboardLayoutDelegate?
65: 
66:   private var isPortrait: Bool {
67:     return UIScreen.mainScreen().bounds.size.width < UIScreen.mainScreen().bounds.size.height
68:   }
69: 
70:   public var typingEnabled: Bool = true
71:   private var currentTouches: [KeyboardButtonTouch] = []
72: 
73:   // MARK: Init
74:   public init(style: KeyboardLayoutStyle, rows: [KeyboardRow]) {
75:     super.init(frame: CGRect.zero)
76:     self.style = style
77:     self.rows = rows
78: 
79:     for row in rows {
80:       addSubview(row)
81:     }
82:   }
