88:   // MARK: Layout
89:   public override func layoutSubviews() {
90:     super.layoutSubviews()
91:     superview?.backgroundColor = style.backgroundColor
92: 
93:     let optimumRowHeight = getOptimumRowHeight()
94:     var currentY: CGFloat = 0
95:     for row in rows {
96:       row.isPortrait = isPortrait
97:       currentY += isPortrait ? row.style.topPadding : row.style.topPaddingLandscape
98:       row.frame = CGRect(
99:         x: 0,
100:         y: currentY,
101:         width: frame.size.width,
102:         height: optimumRowHeight)
103:       currentY += optimumRowHeight + (isPortrait ? row.style.bottomPadding : row.style.bottomPaddingLandscape)
104:     }
105:   }
106: 
107:   private func getRowPaddings() -> CGFloat {
108:     var total = CGFloat(0)
109:     for row in rows {
110:       total += isPortrait ? row.style.topPadding + row.style.bottomPadding : row.style.topPaddingLandscape + row.style.bottomPaddingLandscape
111:     }
112:     return total
113:   }
114: 
115:   private func getOptimumRowHeight() -> CGFloat {
116:     let height = frame.size.height
117:     let totalPaddings = getRowPaddings()
118:     return max(0, (height - totalPaddings) / CGFloat(rows.count))
119:   }
120: 
121:   // MARK: Manage Buttons
122:   public func getKeyboardButton(atRowIndex rowIndex: Int, buttonIndex: Int) -> KeyboardButton? {
123:     if let row = rows[safe: rowIndex], let button = row.characters[safe: buttonIndex] as? KeyboardButton {
124:       return button
125:     }
126:     return nil
127:   }
128: 
129:   public func getKeyboardButton(withIdentifier identifier: String) -> KeyboardButton? {
130:     for row in rows {
131:       for button in row.characters {
132:         if let button = button as? KeyboardButton where button.identifier == identifier {
133:           return button
134:         }
135:       }
136:     }
137:     return nil
138:   }
139: 
140:   public func addKeyboardButton(keyboardButton button: KeyboardButton, rowAtIndex: Int, buttonIndex: Int?) {
141:     if let row = rows[safe: rowAtIndex] {
142:       if let index = buttonIndex where buttonIndex < row.characters.count {
143:         row.characters.insert(button, atIndex: index)
144:       } else {
145:         row.characters.append(button)
146:       }
147:       row.addSubview(button)
148:     }
149:   }
150: 
151:   public func removeKeyboardButton(atRowIndex rowIndex: Int, buttonIndex: Int) -> Bool {
152:     if let row = rows[safe: rowIndex], let button = row.characters[safe: buttonIndex] {
153:       row.characters.removeAtIndex(buttonIndex)
154:       button.removeFromSuperview()
155:       return true
156:     }
157:     return false
158:   }
159: 
160:   // MARK: Touch Handling
161:   public override func touchesBegan(touches: Set<UITouch>, withEvent event: UIEvent?) {
162:     super.touchesBegan(touches, withEvent: event)
163:     delegate?.keyboardLayout?(self, didTouchesBegin: touches)
164: 
165:     if !typingEnabled {
166:       return
167:     }
168: 
169:     // Add valid touches that hit a `KeyboardButton` to `currentTouches` dictionary
170:     for touch in touches {
171:       if let button = hitTest(touch.locationInView(self), withEvent: nil) as? KeyboardButton {
172:         if currentTouches.map({ $0.touch }).contains(touch.key) == false {
173:           currentTouches.append(KeyboardButtonTouch(touch: touch, button: button))
174:         }
175:       }
176:     }
177: 
178:     // Send key press start and end events ordered from current touches
179:     for (index, currentTouch) in currentTouches.enumerate() {
180:       if index == max(0, currentTouches.count - 1) {
181:         delegate?.keyboardLayout?(self, didKeyPressStart: currentTouch.button)
182:         currentTouch.button.showKeyPop(show: true)
183:       } else {
184:         delegate?.keyboardLayout?(self, didKeyPressEnd: currentTouch.button)
185:         currentTouch.button.showKeyPop(show: false)
186:       }
187:     }
188: 
189:     if currentTouches.count > 1 {
190:       currentTouches.removeRange(0..<max(0, currentTouches.count - 1))
191:     }
192:   }
193: 
194:   public override func touchesMoved(touches: Set<UITouch>, withEvent event: UIEvent?) {
195:     super.touchesMoved(touches, withEvent: event)
196:     delegate?.keyboardLayout?(self, didTouchesMove: touches)
197: 
198:     if !typingEnabled {
199:       return
200:     }
201: 
202:     for touch in touches {
203:       if let currentTouch = currentTouches.filter({ $0.touch == touch.key }).first,
204:          button = hitTest(touch.locationInView(self), withEvent: nil) as? KeyboardButton {
205:         if currentTouch.button != button {
206:           delegate?.keyboardLayout?(self, didDraggedInFrom: currentTouch.button, to: button)
207:           currentTouch.button.showKeyPop(show: false)
208:           currentTouch.button = button
209:           currentTouch.button.showKeyPop(show: true)
210:         }
211:       }
212:     }
213:   }
214: 
215:   public override func touchesEnded(touches: Set<UITouch>, withEvent event: UIEvent?) {
216:     super.touchesEnded(touches, withEvent: event)
217:     delegate?.keyboardLayout?(self, didTouchesEnd: touches)
218: 
219:     if !typingEnabled {
220:       return
221:     }
222: 
223:     for touch in touches {
224:       if let currentTouch = currentTouches.filter({ $0.touch == touch.key }).first {
225:         currentTouch.button.showKeyPop(show: false)
226:         delegate?.keyboardLayout?(self, didKeyPressEnd: currentTouch.button)
227:         currentTouches = currentTouches.filter({ $0.touch != touch.key })
228:       }
229:     }
230:   }
231: 
232:   public override func touchesCancelled(touches: Set<UITouch>?, withEvent event: UIEvent?) {
233:     super.touchesCancelled(touches, withEvent: event)
234:     currentTouches.forEach({ $0.button.showKeyPop(show: false) })
235:     currentTouches = []
236:     delegate?.keyboardLayout?(self, didTouchesCancel: touches)
237:   }
238: }
