12: /// This action handler inherits the standard action handler
13: /// and makes demo-specific adjustments to it.
14: class DemoActionHandler: KeyboardAction.StandardActionHandler {
15: 
16:     /// Trigger custom actions for `.image` keyboard actions.
17:     override func action(
18:         for gesture: Keyboard.Gesture,
19:         on action: KeyboardAction
20:     ) -> KeyboardAction.GestureAction? {
21:         let standard = super.action(for: gesture, on: action)
22:         switch gesture {
23:         case .longPress: return longPressAction(for: action) ?? standard
24:         case .release: return releaseAction(for: action) ?? standard
25:         default: return standard
26:         }
27:     }
28:     
29:     /// Save an image to Photos when you long press it.
30:     func longPressAction(
31:         for action: KeyboardAction
32:     ) -> KeyboardAction.GestureAction? {
33:         switch action {
34:         case .image(_, _, let imageName): { [weak self] _ in self?.saveImage(named: imageName) }
35:         default: nil
36:         }
37:     }
38: 
39:     /// Copy an image to the pasteboard when you tap it.
40:     func releaseAction(
41:         for action: KeyboardAction
42:     ) -> KeyboardAction.GestureAction? {
43:         switch action {
44:         case .image(_, _, let imageName): { [weak self] _ in self?.copyImage(named: imageName) }
45:         default: nil
46:         }
47:     }
48: }
49: 
50: private extension DemoActionHandler {
51: 
52:     func alert(_ message: String) {
53:         print("Implement alert functionality if you want.")
54:     }
55: 
56:     func copyImage(named imageName: String) {
57:         guard let image = UIImage(named: imageName) else { return }
58:         guard keyboardContext.hasFullAccess else { return alert("You must enable full access to copy images.") }
59:         guard image.copyToPasteboard() else { return alert("The image could not be copied.") }
60:         alert("Copied to pasteboard!")
61:     }
62:     func handleImageDidSave(withError error: Error?) {
63:         if error == nil { alert("Saved!") }
64:         else { alert("Failed!") }
65:     }
66: 
67:     func saveImage(named imageName: String) {
68:         guard let image = UIImage(named: imageName) else { return }
69:         guard keyboardContext.hasFullAccess else { return alert("You must enable full access to save images.") }
70:         image.saveToPhotos(completion: handleImageDidSave)
71:         alert("Saved to photos!")
72:     }
73: }
74: 
75: private extension UIImage {
76:     
77:     func copyToPasteboard(_ pasteboard: UIPasteboard = .general) -> Bool {
78:         guard let data = pngData() else { return false }
79:         pasteboard.setData(data, forPasteboardType: "public.png")
80:         return true
81:     }
82: }
83: 
84: private extension UIImage {
85:     
86:     func saveToPhotos(completion: @escaping (Error?) -> Void) {
87:         ImageService.default.saveImageToPhotos(self, completion: completion)
88:     }
89: }
90: 
91: 
92: /// This class is used as target by the extension above.
93: private class ImageService: NSObject {
94:     
95:     public typealias Completion = (Error?) -> Void
96: 
97:     public static private(set) var `default` = ImageService()
98:     
99:     private var completions = [Completion]()
100:     
101:     public func saveImageToPhotos(_ image: UIImage, completion: @escaping (Error?) -> Void) {
102:         completions.append(completion)
103:         UIImageWriteToSavedPhotosAlbum(image, self, #selector(saveImageToPhotosDidComplete), nil)
104:     }
105:     
106:     @objc func saveImageToPhotosDidComplete(_ image: UIImage, error: NSError?, contextInfo: UnsafeRawPointer) {
107:         guard completions.count > 0 else { return }
108:         completions.removeFirst()(error)
109:     }
110: }
