8: 
9: import Foundation
10: 
11: 
12: private let backspaceDelay = NSTimeInterval(0.5)
13: private let backspaceRepeat = NSTimeInterval(0.07)
14: 
15: 
16: public final class KeyboardBackspaceKeyController: KeyboardKeyListenerProtocol {
17: 
18:     private var delayTimer: NSTimer?
19:     private var repeatTimer: NSTimer?
20: 
21:     public func keyViewDidSendEvents(controlEvents: UIControlEvents, keyView: KeyboardKeyView, key: KeyboardKey, keyboardMode: KeyboardMode) {
22:         guard key.type == .Backspace else {
23:             return
24:         }
25: 
26:         if [.TouchDown].contains(controlEvents) {
27:             self.keyDownHandler()
28:         }
29:         else if [.TouchDragExit, .TouchCancel, .TouchUpInside, .TouchUpOutside, .TouchDragOutside].contains(controlEvents) {
30:             self.keyUpHandler()
31:         }
32:     }
33: 
34:     private func deleteBackward() {
35:         UIInputViewController.optionalRootInputViewController?.textDocumentProxy.deleteBackward()
36:     }
37: 
38:     private func keyDownHandler() {
39:         self.deleteBackward()
40: 
41:         self.cancelTimers()
42:         self.delayTimer =
43:             NSTimer.scheduledTimerWithTimeInterval(backspaceDelay - backspaceRepeat, target: self, selector: Selector("delayHandler"), userInfo: nil, repeats: false)
44:     }
45: 
46:     private func keyUpHandler() {
47:         self.cancelTimers()
48:     }
49: 
50:     private func cancelTimers() {
51:         self.delayTimer?.invalidate()
52:         self.delayTimer = nil
53:         self.repeatTimer?.invalidate()
54:         self.repeatTimer = nil
55:     }
56: 
57:     internal dynamic func delayHandler() {
58:         self.cancelTimers()
59: 
60:         self.repeatTimer =
61:             NSTimer.scheduledTimerWithTimeInterval(backspaceRepeat, target: self, selector: Selector("repeatHandler"), userInfo: nil, repeats: true)
62:     }
63: 
64:     internal dynamic func repeatHandler() {
65:         self.deleteBackward()
66:         KeyboardSoundService.sharedInstance.playInputSound()
67:     }
68: 
69: }
