164:     public override func hitTest(point: CGPoint, withEvent event: UIEvent?) -> UIView? {
165:         // This is simplified and optimised version of UIResponder's `hitTest`.
166:         guard self.userInteractionEnabled && !self.hidden && self.alpha > 0 else {
167:             return nil
168:         }
