170:         // Is this event inside our frame?
171:         if self.pointInside(point, withEvent:event) {
172:             return self
173:         }
174: 
175:         // Is this event inside interactive popup?
176:         if let _ = self.popupView as? KeyboardKeyAlternateKeysPopupView {
