211:         self.shadowView.frame = boundingBox
212:         self.borderView?.frame = boundingBox
213:         self.underView?.frame = boundingBox
214: 
215:         let boundingView = self.displayView
216: 
217:         // Update shapes
218:         self.keyShape.bounds = boundingView.convertRect(self.bounds, fromView: self)
219:         if let popupShape = self.popupShape, let popupView = self.popupView {
220:             popupShape.bounds = boundingView.convertRect(popupView.bounds, fromView: popupView)
221:             fixIntersection(self.keyShape, second: popupShape)
