242:         CATransaction.setDisableActions(true)
243: 
244:         self.keyShape.createPathsIfNeeded()
245: 
246:         var compoundShape: KeyboardShape!
247: 
248:         if let popupShape = self.popupShape, let connectorShape = self.connectorShape {
249:             popupShape.createPathsIfNeeded()
250:             connectorShape.createPathsIfNeeded()
251: 
252:             let popupAndConnectorShape = KeyboardShape(shapes: [self.popupShape, self.connectorShape])
253:             compoundShape = KeyboardShape(shapes: [self.keyShape, popupAndConnectorShape])
254: 
255:             self.shadowLayer.shadowPath = popupAndConnectorShape.fillPath.CGPath
256:         }
257:         else {
258:             compoundShape = self.keyShape
259:             self.shadowLayer.shadowPath = nil
260:         }
261: 
262:         self.underView?.curve = compoundShape.underPath
263:         self.displayView.curve = compoundShape.fillPath
264:         self.borderView?.curve = compoundShape.edgePath
265: 
266:         CATransaction.commit()
267:     }
268: 
269:     func layoutPopupIfNeeded() {
270:         if self.popupView != nil {
271:             self.shadowView.hidden = false
272:             //self.borderView?.hidden = false
273: 
274:             self.layoutPopup()
275:         }
276:         else {
277:             self.shadowView.hidden = true
278:             //self.borderView?.hidden = true
279:         }
280:     }
281: 
282:     // # Prepare for reuse
283: 
284:     public func prepareForReuse() {
285:         self.needsUpdateKey = true
286:         self.needsUpdateKeyMode = true
287:         self.needsUpdateKeyboardMode = true
288:         self.needsUpdateAppearance = true
289:     }
290: 
291:     // # Updating
292: 
293:     public func updateIfNeeded() {
294:         let needUpdateAppearance = self.needsUpdateKey || self.needsUpdateKeyboardMode || self.needsUpdateKeyMode
295: 
296:         if let appearanceManager = self.appearanceManager where needUpdateAppearance {
297:             self.appearance = appearanceManager.appearanceForVariant(self.appearanceVariant)
298:         }
299: 
300:         self.updateKeyModeIfNeeded()
301:         self.updateKeyIfNeeded()
302:         self.updateAppearanceIfNeeded()
303:     }
304: 
305:     // # Updating `appearance`
306:     public func updateAppearanceIfNeeded() {
307:         guard self.needsUpdateAppearance else {
308:             return
309:         }
310: 
311:         self.needsUpdateAppearance = false
312: 
313:         self.updateAppearance()
314:     }
315: 
316:     internal func updateAppearance() {
317:         let appearance = self.appearance
318:         CATransaction.begin()
319:         CATransaction.setDisableActions(true)
320: 
321:         //if self.labelView.font.pointSize != appearance.keycapTextFontSize {
322:         self.labelView.font = appearance.keycapTextFont
323:         //}
324: 
325:         let isPopup = self.keyMode.popupMode != .None
326: 
327:         let textColor = isPopup ? appearance.popupTextColor : appearance.keycapTextColor
328:         let bodyColor = isPopup ? appearance.popupBodyColor : appearance.keycapBodyColor
329:         let borderColor = isPopup ? appearance.popupBorderColor : appearance.keycapBorderColor
330:         let outerShadowColor = isPopup ? appearance.popupOuterShadowColor : appearance.keycapOuterShadowColor
331:         let borderSize = isPopup ? appearance.popupBorderSize : appearance.keycapBorderSize
332: 
333: 
334:         self.labelView.textColor = textColor
335:         self.contentView?.tintColor = textColor
336: 
337:         self.displayView.fillColor = bodyColor
338:         self.underView?.fillColor = outerShadowColor
339:         self.borderView?.strokeColor = borderColor
340: 
341:         self.borderView?.lineWidth = borderSize
342: 
343:         if self.popupView != nil {
344:             self.displayView.fillColor = bodyColor
345:         }
346: 
347:         if let popupView = self.popupView as? KeyboardKeyPreviewPopupView {
348:             popupView.labelView.textColor = textColor
349:         }
350: 
351:         self.keyShape.cornerRadius = self.appearance.bodyCornerRadius
352:         self.popupShape?.cornerRadius = self.appearance.popupCornerRadius
353: 
354: 
355:         if let contentView = self.contentView as? KeyboardKeyContentView {
356:             contentView.appearance = appearance
357:         }
358: 
359:         CATransaction.commit()
360:     }
361: 
362:     // # Updating `key`
363:     public func updateKeyIfNeeded() {
364:         guard self.needsUpdateKey else {
365:             return
366:         }
367: 
368:         self.needsUpdateKey = false
369: 
370:         self.updateKey()
371:     }
372: 
373:     private func updateKey() {
374:         if let label = self.key.label {
375:             self.labelView.text = label.labelWithShiftMode(self.keyboardMode.shiftMode)
376:         }
377:         else {
378:             self.labelView.text = nil
379:         }
380: 
381:         if let image = self.key.image {
382:             self.contentView = image.view(keyboardMode: self.keyboardMode, keyMode: self.keyMode)
383:         }
384:         else if let contentView = self.key.contentView?.copy() as? UIView {
385:             self.contentView = contentView
386:         }
387:         else {
388:             self.contentView = nil
389:         }
390:     }
391: 
392:     // # Updating `keyMode`
393:     public func updateKeyModeIfNeeded() {
394:         guard self.needsUpdateKeyMode else {
395:             return
396:         }
397: 
398:         self.needsUpdateKeyMode = false
399: 
400:         self.updateKeyMode()
401:     }
402: 
403:     private func updateKeyMode() {
404:         let popupMode = self.keyMode.popupMode
405: 
406:         if popupMode == .None {
407:             self.hidePopup()
408:         }
409:         else {
410:             self.showPopupWithMode(popupMode)
411:         }
412:     }
413: 
414:     private func layoutPopup() {
415:         assert(self.popupView != nil, "Popup not instanciated.")
416: 
417:         if let popup = self.popupView {
418:             popup.frame = popup.adjustedIntrinsicFrame() //self.adjustPopupFrame(self.frameForPopup())
419:         }
420:     }
421: 
422:     public var effectiveKey: KeyboardKey {
423:         if let key = (self.popupView as? KeyboardKeyAlternateKeysPopupView)?.highlightedKey {
424:             return key
425:         }
426: 
427:         return self.key
428:     }
429: 
430:     private func showPopupWithMode(mode: KeyboardKeyPopupTypeMode) {
431:         self.hidePopup()
432: 
433:         let direction = self.appearance.popupDirection
434: 
435:         self.popupShape = KeyboardPopupShape(shape: self.keyShape)
436:         self.popupShape?.cornerRadius = self.appearance.popupCornerRadius // FIXME:
437: 
438:         self.connectorShape = KeyboardConnectorShape(
439:             begin: (shape: self.keyShape, direction: direction),
440:             end: (shape: self.popupShape!, direction: direction.opposite())
441:         )
442: 
443:         switch mode {
444:         case .Preview:
445:             let popupView = KeyboardKeyPreviewPopupView()
446:             popupView.appearance = self.appearance
447:             popupView.labelView.text = self.labelView.text // FIXME:
448:             self.popupView = popupView
449:             break
450:         case .AlternateKeys:
451:             let popupView = KeyboardKeyAlternateKeysPopupView()
452:             popupView.appearance = self.appearance
453:             popupView.alternateKeys = self.key.alternateKeys
454:             self.popupView = popupView
455:             break
456:         default:
457:             assertionFailure("KeyboardKeyView: Wrong popupMode.")
458:         }
459: 
460:         self.addSubview(self.popupView!)
461: 
462:         self.contentVisible = false
463:         self.zIndexed = true
464: 
465:         self.needsUpdateAppearance = true
466:     }
467: 
468:     private func hidePopup() {
469:         guard self.popupView != nil else {
470:             return
471:         }
472: 
473:         self.connectorShape = nil
474:         self.popupShape = nil
475: 
476:         self.popupView!.removeFromSuperview()
477:         self.popupView = nil
478: 
479:         self.contentVisible = true
480:         self.zIndexed = false
481: 
482:         self.needsUpdateAppearance = true
483:     }
484: 
485: }
