135: 
136:     private func establishKeyViews(pageNumber pageNumber: Int) {
137:         CATransaction.begin()
138:         CATransaction.setDisableActions(true)
139: 
140:         self.establishKeyViews(
141:             page: self.keyboardLayout.pages[pageNumber],
142:             pageLayoutController: self.pageLayoutControllers[pageNumber]
143:         )
144: 
145:         CATransaction.commit()
146:     }
147: 
148:     private func initializePageLayoutControllers() {
149:         self.pageLayoutControllers = self.keyboardLayout.pages.map {
150:             KeyboardPageLayoutController(page: $0)
151:         }
152:     }
153: 
154:     private func establishKeyViews(page page: KeyboardPage, pageLayoutController: KeyboardPageLayoutController) {
155:         // Setup `KeyboardPageLayoutController`.
156:         pageLayoutController.bounds = self.view.bounds
157: 
158:         // Return all object from a set to a pool and then clean the set.
159:         self.keyViewPool.storeSet(self.keyViewSet)
160:         self.keyViewSet.removeAll()
161: 
162:         let keyFrames = pageLayoutController.keyFrames()
163: 
164:         for (key, frame) in keyFrames {
165:             let keyView = self.retrieveKeyViewUsingPool(key: key, frame: frame)
166: 
167:             self.keyViewSet.insert(key, keyView: keyView)
168:         }
169: 
170:         // Apply `hidden` property.
171:         for view in self.keyViewPool.keyViews { view.hidden = true }
172:         for view in self.keyViewSet.views { view.hidden = false }
173: 
174:         self.updateKeyViewsIfNeeded()
175: 
176:         self.keyboardView.resetTrackedViews()
177:         self.listenerCoordinator.registerKeyViews()
178:     }
179: 
180:     private func layoutKeyViewsIfNeeded() {
181:         let pageLayoutController = self.pageLayoutControllers[self.pageNumber]
182: 
183:         if pageLayoutController.bounds == self.view.bounds {
184:             return
185:         }
186: 
187:         self.layoutKeyViews()
188:     }
189: 
190:     private func layoutKeyViews() {
191:         CATransaction.begin()
192:         CATransaction.setDisableActions(true)
193: 
194:         let pageLayoutController = self.pageLayoutControllers[self.pageNumber]
195:         pageLayoutController.bounds = self.view.bounds
196: 
197:         let keyFrames = pageLayoutController.keyFrames()
198: 
199:         for (key, frame) in keyFrames {
200:             let keyView = self.keyViewSet.viewByKey(key)!
201:             keyView.frame = frame
202:         }
203: 
204:         CATransaction.commit()
205:     }
206: 
207:     private func retrieveKeyViewUsingPool(key key: KeyboardKey, frame: CGRect) -> KeyboardKeyView {
208:         if let keyView = self.keyViewPool.restore(size: frame.size, keyType: key.type) {
209:             keyView.prepareForReuse()
210:             keyView.frame.origin = frame.origin
211:             return keyView
212:         }
213: 
214:         let keyView = self.createAndRegisterKeyView(key: key)
215:         keyView.frame = frame
216:         return keyView
217:     }
218: 
219:     private func createAndRegisterKeyView(key key: KeyboardKey) -> KeyboardKeyView {
220:         let keyView = KeyboardKeyView()
221:         keyView.appearanceManager = self.appearanceManager
222:         self.view.addSubview(keyView)
223:         return keyView
224:     }
225: 
226:     internal func updateKeyViewsIfNeeded() {
227:         CATransaction.begin()
228:         CATransaction.setDisableActions(true)
229: 
230:         self.updateKeyboardAppearance()
231: 
232:         for (key, keyView) in self.keyViewSet {
233:             keyView.key = key
234:             keyView.keyboardMode = self.keyboardMode
235:             keyView.updateIfNeeded()
236:         }
237: 
238:         CATransaction.commit()
239:     }
240: 
241:     func keyboardModeDidSet(oldValue: KeyboardMode) {
242:         guard self.keyboardMode != oldValue else {
243:             return
244:         }
245: 
246:         self.updateKeyViewsIfNeeded()
247:     }
248: 
249:     private func updateKeyboardColorMode() {
250:         self.keyboardMode.colorMode = KeyboardColorMode.suitable()
251:     }
252: 
253:     private func updateKeyboardAppearance() {
254:         var appearanceVariant = KeyboardAppearanceVariant()
255:         appearanceVariant.colorMode = self.keyboardMode.colorMode
256: 
257:         let backgorundColor = self.appearanceManager.theme.keyboardBackgroundColorWithAppearanceVariant(appearanceVariant)
258:         if let rootInputViewController = UIInputViewController.rootInputViewController as? RootInputViewController {
259:             rootInputViewController.backgroundView.backgroundColor = backgorundColor
260:         }
261:         else {
262:             self.keyboardView.backgroundColor = backgorundColor
263:         }
264:     }
265: 
266: }
