2: //  KeyboardView.swift
3: //  KeyboardKit
4: //
5: //  Created by Valentin Shergin on 1/12/16.
6: //  Copyright © 2016 AnchorFree. All rights reserved.
7: //
8: 
9: import UIKit
10: 
11: internal final class KeyboardView: UIView {
12: 
13:     override static func requiresConstraintBasedLayout() -> Bool {
14:         return true
15:     }
16: 
17:     var touchToView: [UITouch:UIView]
18:     
19:     override init(frame: CGRect) {
20:         self.touchToView = [:]
21:         
22:         super.init(frame: frame)
23:         
24:         self.contentMode = UIViewContentMode.Redraw
25:         self.multipleTouchEnabled = true
26:         self.userInteractionEnabled = true
27:         self.opaque = false
28:     }
29: 
30:     required init?(coder: NSCoder) {
31:         fatalError("NSCoding not supported")
32:     }
33: 
34:     override func intrinsicContentSize() -> CGSize {
35:         let interfaceOrientation = UIApplication.🚀sharedApplication().statusBarOrientation
36:         let isPad = UIDevice.currentDevice().userInterfaceIdiom == UIUserInterfaceIdiom.Pad
37:         let actualScreenWidth = (UIScreen.mainScreen().nativeBounds.size.width / UIScreen.mainScreen().nativeScale)
38:         let canonicalPortraitHeight = (isPad ? CGFloat(264) : CGFloat(interfaceOrientation.isPortrait && actualScreenWidth >= 400 ? 226 : 216))
39:         let canonicalLandscapeHeight = (isPad ? CGFloat(352) : CGFloat(162))
40:         let canonicalHeight = interfaceOrientation.isPortrait ? canonicalPortraitHeight : canonicalLandscapeHeight
41:         return CGSize(width: actualScreenWidth, height: canonicalHeight)
42:     }
43: 
44:     // Why have this useless drawRect? Well, if we just set the backgroundColor to clearColor,
45:     // then some weird optimization happens on UIKit's side where tapping down on a transparent pixel will
46:     // not actually recognize the touch. Having a manual drawRect fixes this behavior, even though it doesn't
47:     // actually do anything.
48:     override func drawRect(rect: CGRect) {}
49: 
50:     override func hitTest(point: CGPoint, withEvent event: UIEvent!) -> UIView? {
51:         guard !self.hidden && self.alpha > 0 && self.userInteractionEnabled else {
52:             return nil
53:         }
54: 
55:         return self.bounds.contains(point) ? self : nil
56:     }
57: 
58:     func handleControl(view: UIView?, controlEvent: UIControlEvents, event: UIEvent?) {
59:         guard let controlView = view as? UIControl else {
60:             return
61:         }
62: 
63:         for target in controlView.allTargets() {
64:             guard let actions = controlView.actionsForTarget(target, forControlEvent: controlEvent) else {
65:                 continue
66:             }
67: 
68:             for action in actions {
69:                 controlView.sendAction(Selector(action), to: target, forEvent: event)
70:             }
71:         }
72:     }
73: 
74:     func findNearestView(position: CGPoint) -> UIView? {
75:         guard self.bounds.contains(position) else {
76:             return nil
77:         }
78:         
79:         var closest: (view: UIView, distance: CGFloat)!
80:         
81:         for view in self.subviews {
82:             guard !view.hidden else {
83:                 continue
84:             }
85: 
86:             let distance = view.frame.distanceTo(position)
87: 
88:             if closest == nil || closest.distance > distance {
89:                 closest = (view: view, distance: distance)
90:             }
91:         }
92: 
93:         guard closest != nil else {
94:             return nil
95:         }
96: 
97:         return closest.view
98:     }
99: 
100:     func resetTrackedViews() {
101:         for view in self.touchToView.values {
102:             self.handleControl(view, controlEvent: .TouchCancel, event: nil)
103:         }
104: 
105:         self.touchToView.removeAll(keepCapacity: true)
106:     }
107: 
108:     func ownView(newTouch: UITouch, viewToOwn: UIView?) -> Bool {
109:         var foundView = false
110: 
111:         if viewToOwn != nil {
112:             for (touch, view) in self.touchToView {
113:                 if viewToOwn == view {
114:                     if touch == newTouch {
115:                         break
116:                     }
117:                     else {
118:                         self.touchToView[touch] = nil
119:                         foundView = true
120:                     }
121:                     break
122:                 }
123:             }
124:         }
125: 
126:         self.touchToView[newTouch] = viewToOwn
127:         return foundView
128:     }
129: 
130:     override func touchesBegan(touches: Set<UITouch>, withEvent event: UIEvent?) {
131:         for touch in touches {
132:             let position = touch.locationInView(self)
133:             let view = findNearestView(position)
134:             
135:             let viewChangedOwnership = self.ownView(touch, viewToOwn: view)
136:             
137:             if !viewChangedOwnership {
138:                 self.handleControl(view, controlEvent: .TouchDown, event: event)
139:                 
140:                 if touch.tapCount > 1 {
141:                     // two events, I think this is the correct behavior but I have not tested with an actual UIControl
142:                     self.handleControl(view, controlEvent: .TouchDownRepeat, event: event)
143:                 }
144:             }
145:         }
146:     }
147: 
148:     override func touchesMoved(touches: Set<UITouch>, withEvent event: UIEvent?) {
149:         for touch in touches {
150:             let position = touch.locationInView(self)
151:             
152:             let oldView = self.touchToView[touch]
153:             var newView: UIView?
154: 
155:             if oldView != nil {
156:                 let point = touch.locationInView(oldView!)
157:                 let hitView = oldView!.hitTest(point, withEvent: event)
158: 
159:                 if hitView != nil {
160:                     newView = oldView
161:                 }
162:             }
163: 
164:             newView = newView ?? findNearestView(position)
165: 
166:             if oldView != newView {
